-- Upgrade an existing Supabase reference schema to Qwen3 Embedding's
-- 1024-dimensional default vectors. Chunk text and page references are kept;
-- incompatible vectors are cleared so they must be regenerated by Ollama.
ALTER TABLE public.document_chunks
  ADD COLUMN IF NOT EXISTS embedding_model text;

ALTER TABLE public.document_chunks
  ALTER COLUMN embedding TYPE vector(1024)
  USING NULL::vector(1024);

CREATE INDEX IF NOT EXISTS document_chunks_embedding_idx
  ON public.document_chunks USING hnsw (embedding vector_cosine_ops);
